#!/usr/bin/env python3
"""Compile data/soldier_world_fixture.json.gz into build/soldier_world_fixture.h."""
import gzip,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
src=Path(sys.argv[1]) if len(sys.argv)>1 else ROOT/'data/soldier_world_fixture.json.gz'
with gzip.open(src,'rt') as f:d=json.load(f)
F=['routine','flags15','flash','field18','word1e','anim','timer','speed','x','y','vx','vy','parent','px','py','cx','cy',
   'mark','correction','health','field50','timer5a','f5b','f5c','f5d','f5e','flags5f','scalar62','field66','variant68','group69','kind_angle']
def s32(v):return v-(1<<32) if v&0x80000000 else v
L=['/* Generated by tools/compile_soldier_world.py; do not edit. */','#include <stddef.h>','#include <stdint.h>','#include <stdbool.h>',
   'typedef struct { uint32_t '+','.join(F)+'; uint8_t locals[38]; } world_snapshot_t;',
   'typedef struct { uint32_t node; world_snapshot_t s; } world_soldier_t;',
   'typedef struct { uint32_t node,routine; int32_t x,y; } world_throw_t;',
   'typedef struct { uint32_t node; uint8_t kind; uint16_t position; bool created; } world_actor_t;',
   'typedef struct { uint32_t node; uint16_t value; } world_call_t;',
   'typedef struct { uint16_t position; int32_t x,y,vx,vy; uint32_t parent; int32_t px,py,cx,cy; uint8_t flags15,flags5f,mark,correction,f6f,f5e; uint16_t kind_angle; } world_bullet_t;',
   'typedef struct { uint32_t frame; int32_t scroll_x,scroll_y; uint8_t epoch; uint16_t video; uint16_t player_x,player_y; uint8_t player_flags15; bool player_alive,player_dead;',
   '  const world_actor_t *order; uint8_t order_count; const world_call_t *log; uint16_t log_count; const world_bullet_t *bullets; uint8_t bullet_count;',
   '  uint16_t rng_words[55]; uint8_t rng_cursor; uint32_t pc; uint8_t groups[9]; uint16_t grid[128]; const world_soldier_t *soldiers; uint8_t soldier_count; const world_throw_t *throws; uint8_t throw_count; } world_tick_t;',
   'typedef struct { const char *name; uint8_t epoch; uint16_t rng_words[55]; uint8_t rng_cursor; uint32_t pc; int32_t scroll_x; uint16_t grid[128]; uint8_t grid_cursor; const world_tick_t *ticks; unsigned tick_count; } world_capture_t;']
def snap(s,loc):return '{'+','.join('0x%xu'%(s[k]&0xffffffff) for k in F)+',{'+','.join(map(str,loc))+'}}'
for i,c in enumerate(d['captures']):
    for j,t in enumerate(c['ticks']):
        e=t['expect']
        L.append('static const world_actor_t world_order_%d_%d[]={'%(i,j)+','.join('{0x%x,%d,%d,%d}'%(a['node'],a['kind'],a['position'],1 if a['created'] else 0) for a in t['order'])+'};')
        if t['log']:L.append('static const world_call_t world_log_%d_%d[]={'%(i,j)+','.join('{0x%x,%d}'%(a['node'],a['value']) for a in t['log'])+'};')
        if t['bullets']:L.append('static const world_bullet_t world_bullets_%d_%d[]={'%(i,j)+','.join('{%d,%d,%d,%d,%d,0x%x,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,0x%x}'%(
            b['position'],s32(b['body']['x']),s32(b['body']['y']),s32(b['body']['vx']),s32(b['body']['vy']),b['body']['parent'],
            s32(b['body']['px']),s32(b['body']['py']),s32(b['body']['cx']),s32(b['body']['cy']),b['flags15'],b['flags5f'],b['mark'],b['correction'],
            b['f6f'],b['f5e'],b['kind_angle']) for b in t['bullets'])+'};')
        if e['soldiers']:L.append('static const world_soldier_t world_soldiers_%d_%d[]={'%(i,j)+','.join('{0x%s,%s}'%(n,snap(v['after'],v['locals'])) for n,v in e['soldiers'].items())+'};')
        if e['throws']:L.append('static const world_throw_t world_throws_%d_%d[]={'%(i,j)+','.join('{0x%s,0x%x,%d,%d}'%(n,v['routine'],s32(v['x']),s32(v['y'])) for n,v in e['throws'].items())+'};')
    L.append('static const world_tick_t world_ticks_%d[]={'%i)
    for j,t in enumerate(c['ticks']):
        e=t['expect'];p=t['player']
        L.append('  {%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,world_order_%d_%d,%d,%s,%d,%s,%d,{%s},%d,0x%x,{%s},{%s},%s,%d,%s,%d},'%(t['frame'],s32(t['scroll_x']),s32(t['scroll_y']),t['epoch'],t['video'],
            p['px'],p['py'],p['flags15'],1 if p['alive'] else 0,1 if p['dead'] else 0,i,j,len(t['order']),
            'world_log_%d_%d'%(i,j) if t['log'] else 'NULL',len(t['log']),'world_bullets_%d_%d'%(i,j) if t['bullets'] else 'NULL',len(t['bullets']),
            ','.join(map(str,e['rng']['words'])),e['rng']['cursor'],e['pc'],','.join(map(str,e['groups'])),','.join(map(str,e['grid'])),
            'world_soldiers_%d_%d'%(i,j) if e['soldiers'] else 'NULL',len(e['soldiers']),'world_throws_%d_%d'%(i,j) if e['throws'] else 'NULL',len(e['throws'])))
    L.append('};')
L.append('static const world_capture_t world_captures[]={'+','.join('{"%s",%d,{%s},%d,0x%x,%d,{%s},%d,world_ticks_%d,%d}'%(c['capture'],c['epoch'],
    ','.join(map(str,c['rng']['words'])),c['rng']['cursor'],c['pc'],s32(c['scroll_x']),
    ','.join(str(c['grid'][k]<<8|c['grid'][k+1]) for k in range(0,256,2)),c['grid_cursor'],i,len(c['ticks'])) for i,c in enumerate(d['captures']))+'};')
(ROOT/'build').mkdir(exist_ok=True);(ROOT/'build/soldier_world_fixture.h').write_text('\n'.join(L)+'\n')
print(sum(len(c['ticks']) for c in d['captures']),'world updates')
